    "core.story.1.title": "What stays with you",
    "core.story.1.body": "Money comes and goes. Jobs change, plans slip, circumstances are sometimes stronger than we are. But every path needs something that stays with you. That is what Core is for.",
    "core.story.2.title": "Yours alone",
    "core.story.2.body": "Core is personal: it cannot be transferred, sold or taken away. And it never decreases. No missed day, hard week or mistake takes away what you have already built.",
    "core.story.3.title": "It works every day",
    "core.story.3.body": "While you live your life, Core produces a calculated income: currently 0.0633% per day. You can return part of it to Core so it grows faster, and the rest goes to Wallet. This is a calculation under the system's rules, not a promise of income.",
    "core.story.4.title": "You set the pace",
    "core.story.4.body": "Core grows from useful steps you carry to a result and from money you choose to add from Wallet. Core never returns to Wallet, so add what you are ready to leave growing for a long time.",
