    "invite.rules": "Write to one person at a time, no mass mailings. Do not name amounts or promise income: task rewards are internal Core points.",
    "invite.text.1": "I looked into Open Abundance and got hooked: people share how they are making their wishes happen, from trips to small projects of their own. See for yourself while it is still fresh: {link}",
    "invite.text.2": "While everyone is talking about AI, this app already uses it to help people with real wishes: what to do today, where to start, how not to quit. Have a look: {link}",
    "invite.text.3": "It is curious to see what others are up to: some learn something new, some start small services and side gigs, some save for a dream. Take a look and compare with your own plans: {link}",
    "invite.text.4": "You pick your wish in a couple of minutes and see the first step, and there is also a daily accrual on your points, the app shows how much. Free: {link}",
    "invite.text.5": "Look what I found: {link}. People make wishes happen together with an AI. Easier to see once than to explain.",
