    "marketTemplate.1.title": "Proofread a text of up to 2 pages",
    "marketTemplate.1.description": "I fix spelling, punctuation and typos in a text of up to 2 pages. You send the text as a file or link; I return a corrected version with the changes marked. I do not rewrite meaning or style.",
    "marketTemplate.2.title": "Transcribe audio up to 15 minutes",
    "marketTemplate.2.description": "I turn a recording of up to 15 minutes into text. You send audio or video with clear speech; I return text split into paragraphs with unclear parts marked.",
    "marketTemplate.3.title": "Design a cover for a post or video",
    "marketTemplate.3.description": "One cover in the size you need with your headline. You send the text, a style example and photos if any; I send the final file and one revision on request.",
    "marketTemplate.4.title": "Find 10 gift ideas within your budget",
    "marketTemplate.4.description": "I pick 10 gift options with links and a short reason for each. You tell me who it is for, the budget and a couple of interests. You make the purchase yourself.",
    "marketTemplate.5.title": "Review a CV with 5 concrete edits",
    "marketTemplate.5.description": "I read your CV and send 5 concrete edits: what to remove, what to add, how to phrase it. You send the CV and the role you want. No interview guarantee — the goal is a clearer CV.",
    "marketTemplate.6.title": "Build a monthly expense spreadsheet",
    "marketTemplate.6.description": "A simple Google Sheets table with categories and monthly totals. You name your categories; I send a link and a short guide on adding expenses.",
    "marketTemplate.7.title": "Translate a short text RU ↔ EN, up to 1 page",
    "marketTemplate.7.description": "I translate up to 1 page between Russian and English. Good for letters, descriptions and posts; not for legal or medical documents.",
    "marketTemplate.8.title": "Write your sale listing",
    "marketTemplate.8.description": "I write a clear title and description for one listing and suggest which 3–5 photos to take. You tell me what you sell and its condition; you publish it yourself.",
    "marketTemplate.9.title": "Weekly to-do template",
    "marketTemplate.9.description": "A ready weekly planning template in PDF and Google Sheets: weekly goals, three key tasks a day, space for a review. The file arrives right after purchase.",
    "marketTemplate.10.title": "Help someone get comfortable with a smartphone",
    "marketTemplate.10.description": "One online session up to 45 minutes: set up the needed apps, notifications and backup. Good for helping a relative. I never ask for passwords — you enter them yourself.",
